<?php require_login();$st=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$st->execute([auth()['id']]);$orders=$st->fetchAll();?><section class="page-heading compact"><div class="container"><span class="eyebrow">WELCOME BACK, <?=h(strtoupper(auth()['name']))?></span><h1>My <em>orders.</em></h1></div></section><section class="container section"><div class="orders-top"><p>View and follow your delicious deliveries.</p><form method="post" action="<?=h(url('logout'))?>"><?=csrf_input()?><button class="small-btn" type="submit">Sign out</button></form></div><?php if(!$orders):?><div class="empty-state"><span>♡</span><h2>No orders yet</h2><p>Your first delicious adventure is waiting.</p><a class="btn btn-primary" href="<?=h(url('shop'))?>">Start shopping ↗</a></div><?php else:?><div class="order-list"><?php foreach($orders as $o):?><article class="order-card"><div><span class="eyebrow">ORDER #<?=intval($o['id'])?></span><h3><?=date('M j, Y',strtotime($o['created_at']))?></h3><small><?=h($o['payment_method']==='pickup'?'Store pickup':'Cash on delivery')?></small></div><span class="status <?=h($o['status'])?>"><?=h(ucfirst($o['status']))?></span><strong><?=h(money($o['total']))?></strong></article><?php endforeach;?></div><?php endif;?></section>
